<?php
require_once '../config/app.php'; require_once '../includes/security.php'; start_secure_session(); require_permission('subscriptions.manage'); $pdo=db(); $error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['_csrf']??'')){ $error='Invalid request.'; }
 else {
  $id=(int)($_POST['id']??0); $name=trim($_POST['plan_name']??''); $days=max(1,(int)($_POST['duration_days']??1)); $price=max(0,(float)($_POST['price']??0)); $features=trim($_POST['features']??''); $status=($_POST['status']??'active')==='inactive'?'inactive':'active'; $trial=isset($_POST['is_trial'])?1:0; $sort=(int)($_POST['sort_order']??0);
  if($name==='') $error='Plan name is required.'; else { if($id){$st=$pdo->prepare("UPDATE subscription_plans SET plan_name=?,duration_days=?,price=?,features=?,status=?,is_trial=?,sort_order=? WHERE id=?");$st->execute([$name,$days,$price,$features,$status,$trial,$sort,$id]);}else{$st=$pdo->prepare("INSERT INTO subscription_plans(plan_name,duration_days,price,features,status,is_trial,sort_order) VALUES(?,?,?,?,?,?,?)");$st->execute([$name,$days,$price,$features,$status,$trial,$sort]);} flash('success','Plan saved.'); redirect('subscription-plans.php'); }
 }
}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM subscription_plans WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$plans=$pdo->query('SELECT * FROM subscription_plans ORDER BY sort_order,id')->fetchAll();$page_title='Subscription Plans';$asset_prefix='../';$home_link='../index.php';require '../includes/header.php';
?><div class="page-head"><div><span class="eyebrow">ADMIN</span><h1>Subscription Plans</h1><p class="muted">Configure trial and paid plans. Payment gateway credentials are not stored here.</p></div></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="card"><h2><?= $edit?'Edit Plan':'Create Plan' ?></h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="grid-2"><label>Plan Name<input name="plan_name" value="<?=e($edit['plan_name']??'')?>" required></label><label>Duration (days)<input type="number" min="1" name="duration_days" value="<?=e($edit['duration_days']??30)?>" required></label><label>Price (INR)<input type="number" min="0" step="0.01" name="price" value="<?=e($edit['price']??0)?>" required></label><label>Sort Order<input type="number" name="sort_order" value="<?=e($edit['sort_order']??0)?>"></label><label>Status<select name="status"><option value="active" <?=($edit['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive" <?=($edit['status']??'')==='inactive'?'selected':''?>>Inactive</option></select></label><label><input type="checkbox" name="is_trial" <?=!empty($edit['is_trial'])?'checked':''?>> Free Trial plan</label></div><label>Features (separate with semicolons)<textarea name="features" rows="3"><?=e($edit['features']??'Profile; Job matching; Alerts; Application assistance')?></textarea></label><button class="btn btn-primary">Save Plan</button></form></div>
<div class="card"><h2>Existing Plans</h2><table><thead><tr><th>Plan</th><th>Days</th><th>Price</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($plans as $p):?><tr><td><?=e($p['plan_name'])?></td><td><?=e($p['duration_days'])?></td><td>₹<?=number_format((float)$p['price'],2)?></td><td><?=!empty($p['is_trial'])?'Trial':'Paid'?></td><td><?=e($p['status'])?></td><td><a href="?edit=<?=e($p['id'])?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div>
